+        border-color: var(--primary);
+        background: var(--primary-soft);
+        box-shadow: 0 10px 24px rgba(37, 99, 235, 0.12);
+      }
+
+      input[type="radio"] {
+        width: 1.15rem;
+        height: 1.15rem;
+        margin: 0;
+        accent-color: var(--primary);
+      }
+
+      .option-text {
+        font-weight: 650;
+      }
+
+      button {
+        width: 100%;
+        border: 0;
+        border-radius: 0.95rem;
+        padding: 0.95rem 1.25rem;
+        background: var(--primary);
+        color: #ffffff;
+        font: inherit;
+        font-weight: 700;
